import { PDFDocument, StandardFonts, rgb } from "pdf-lib";

const CAPA_COMERCIAL_B64 = "";

const CAPA_TECNICA_B64 = "";

function carregarModelo(tipo: "comercial" | "tecnica"): Buffer {
  const b64 = tipo === "comercial" ? CAPA_COMERCIAL_B64 : CAPA_TECNICA_B64;
  return Buffer.from(b64, "base64");
}

interface DadosCapa {
  clienteRazaoSocial: string;
  numeroProposta: string;
  versao: number;
  cidade: string;
  data: string;
}

export async function combinarCapaComConteudo(
  tipo: "comercial" | "tecnica",
  dados: DadosCapa,
  conteudoPdfBytes: Buffer | Uint8Array
): Promise<Uint8Array> {
  const modeloBytes = carregarModelo(tipo);
  const modeloDoc = await PDFDocument.load(modeloBytes);
  const conteudoDoc = await PDFDocument.load(conteudoPdfBytes);

  const resultado = await PDFDocument.create();

  const [capaPagina] = await resultado.copyPages(modeloDoc, [0]);

  const font = await resultado.embedFont(StandardFonts.Helvetica);
  const fontBold = await resultado.embedFont(StandardFonts.HelveticaBold);
  const { width, height } = capaPagina.getSize();

  const navy = rgb(15 / 255, 23 / 255, 42 / 255);
  capaPagina.drawRectangle({
    x: 0,
    y: height - 770,
    width,
    height: 85,
    color: navy,
    borderWidth: 0,
  });

  const textos = [
    { text: dados.clienteRazaoSocial, font: fontBold, size: 12 },
    { text: `Proposta ${dados.numeroProposta}`, font, size: 10.5 },
    { text: `versão ${dados.versao}`, font, size: 10.5 },
    { text: `${dados.cidade}, ${dados.data}`, font: fontBold, size: 10.5 },
  ];

  let y = height - 705;
  for (const t of textos) {
    const textWidth = t.font.widthOfTextAtSize(t.text, t.size);
    capaPagina.drawText(t.text, {
      x: (width - textWidth) / 2,
      y,
      size: t.size,
      font: t.font,
      color: rgb(1, 1, 1),
    });
    y -= t.size + 5;
  }

  resultado.addPage(capaPagina);

  const conteudoIndices = Array.from({ length: conteudoDoc.getPageCount() }, (_, i) => i);
  const paginas = await resultado.copyPages(conteudoDoc, conteudoIndices);
  for (const p of paginas) {
    resultado.addPage(p);
  }

  return resultado.save();
}
